export async function search(query: string, docs: string[], docVectors: number[][], k = 3) {
  const [q] = await embed([query]);
  return docVectors
    .map((vector, index) => ({ score: cosine(q, vector), doc: docs[index] }))
    .sort((a, b) => b.score - a.score)
    .slice(0, k);
}
